WFJ.Data.add("spell", {
  [1226001] = { "Altera un campo magnetico tra te e il nemico vicino che hai come bersaglio, respingendovi a vicenda.\n\nHa effetto solo su bersagli fino a $N1 livelli superiori al tuo. Alcuni bersagli non possono essere spostati. Un bersaglio può subire questo effetto solo una volta ogni $D1.", nil, 0x84421a5f, nil, "um" },
  [1226007] = { "Altera un campo magnetico tra te e il nemico vicino che hai come bersaglio, respingendovi a vicenda.\n\nHa effetto solo su bersagli fino a $N1 livelli superiori al tuo. Alcuni bersagli non possono essere spostati. Un bersaglio può subire questo effetto solo una volta ogni $D1.", nil, 0xf3b3d2c1, nil, "um" },
  [1226013] = { "Altera un campo magnetico tra te e il nemico vicino che hai come bersaglio, respingendovi a vicenda.\n\nHa effetto solo su bersagli fino a $N1 livelli superiori al tuo. Alcuni bersagli non possono essere spostati. Un bersaglio può subire questo effetto solo una volta ogni $D1.", nil, 0x84421a5f, nil, "um" },
  [1226022] = { "Altera un campo magnetico tra te e il nemico vicino che hai come bersaglio, respingendovi a vicenda.\n\nHa effetto solo su bersagli fino a $N1 livelli superiori al tuo. Alcuni bersagli non possono essere spostati. Un bersaglio può subire questo effetto solo una volta ogni $D1.", nil, 0x84421a5f, nil, "um" },
  [1226032] = { "Ogni volta che il tuo Bocciolo di Vita cura un bersaglio, ha una probabilità del $N1% di rendere istantaneo il tuo prossimo ⟦Healing Touch=Tocco Curativo⟧, Nutrizione o Ricrescita lanciato entro $D1.", nil, 0xffe86700, nil, "um" },
  [1226035] = { "Riduce del $N1% il tempo di lancio del tuo prossimo ⟦Healing Touch=Tocco Curativo⟧, Ricrescita o Nutrizione.", "Tempo di lancio del tuo prossimo ⟦Healing Touch=Tocco Curativo⟧, Ricrescita o Nutrizione ridotto del $N1%.", 0x240482bc, 0x3ab69cad, "uu" },
  [1226038] = { "Riduce del $N1% il tempo di lancio del tuo prossimo ⟦Healing Touch=Tocco Curativo⟧, Ricrescita o Nutrizione.", "Cure ricevute dall'incantatore di questo Rinvigorimento aumentate del $N1%.", 0x240482bc, 0xcf0f5f9e, "uu" },
  [1226040] = { "I bersagli su cui è attivo il tuo Rinvigorimento di Grado $N1 o di Grado $N2 ricevono il $N3% di cure in più dai tuoi incantesimi.", nil, 0x58ef5859, nil, "um" },
  [1226044] = { "Le cure non periodiche della tua Ricrescita di Grado $N1 o di Grado $N2 hanno una probabilità del $N3% di estendere il tuo Rinvigorimento presente su quel bersaglio a tutti i membri del suo gruppo entro $N4 m che non sono già sotto l'effetto del tuo Rinvigorimento.", nil, 0x51b44b42, nil, "um" },
  [1226045] = { "Altera un campo magnetico tra te e il nemico vicino che hai come bersaglio, respingendovi a vicenda.\n\nHa effetto solo su bersagli fino a $N1 livelli superiori al tuo. Alcuni bersagli non possono essere spostati. Un bersaglio può subire questo effetto solo una volta ogni $D1.", "Un nemico ha da poco perturbato il tuo campo magnetico, che per un breve periodo non può essere usato contro di te.", 0x84421a5f, 0x57c0ecaf, "uu" },
  [1226092] = { "Il tuo Fuoco Stellare infligge il $N1% di danni in più ai bersagli colpiti dal tuo Fuoco Lunare, e la tua Ira Silvana infligge il $N2% di danni in più ai bersagli colpiti dal tuo Fuoco Solare.", nil, 0xe8d829ca, nil, "um" },
  [1226103] = { "La tua Cometa Arcana ora aumenta i danni dei tuoi prossimi $N1 incantesimi Fuoco Stellare.", nil, 0x2dc919bb, nil, "um" },
  [1226105] = { nil, "Aumenta del $N1% i danni inflitti dalla tua prossima Ira Silvana.", nil, 0x5b9f4263, "mu" },
  [1226106] = { nil, "Aumenta del $N1% i danni inflitti dal tuo prossimo Fuoco Stellare.", nil, 0x7bbe5aa0, "mu" },
  [1226108] = { "Ogni volta che il tuo Fuoco Solare infligge danni periodici, ottieni il $N1% di danni in più per la tua prossima Ira Silvana, effetto cumulabile fino a $N2 volte. Ogni volta che il tuo Fuoco Lunare infligge danni periodici, ottieni il $N3% di danni in più per il tuo prossimo Fuoco Stellare, effetto cumulabile fino a $N4 volte. Questi bonus non si applicano a Cometa Arcana.", nil, 0x308c40d3, nil, "um" },
  [1226109] = { "Ottieni $N1 energia ogni volta che Graffio o Squarcio infliggono danni periodici.", nil, 0x317e6f05, nil, "um" },
  [1226116] = { "Moltiplica per $N1 il bonus ai danni di ⟦Tiger's Fury=Furia della Tigre⟧.", nil, 0x78baa101, nil, "um" },
  [1226119] = { "Le tue mosse risolutive hanno una probabilità del $N1% per punto combo speso di attivare Lancio Istintivo e di prolungare di $D1 la durata della tua ⟦Tiger's Fury=Furia della Tigre⟧ attiva.", nil, 0x0bb9bdeb, nil, "um" },
  [1226121] = { "I tuoi colpi critici in mischia in ⟦Bear Form=Forma d'Orso⟧ o in ⟦Dire Bear Form=Forma d'Orso Crudele⟧ ti conferiscono uno scudo che dura $D1 e assorbe danni fisici pari al $N2% della tua potenza d'attacco la prossima volta che subisci danni fisici. Si accumula fino a $N3 volte.", nil, 0x6a8c7b34, nil, "um" },
  [1226125] = { "Aumenta di $D1 la durata della tua abilità Berserk.", nil, 0x80f97bb5, nil, "um" },
  [1226126] = { "Ottieni il $N1% di velocità d'attacco in più per $D1 ogni volta che infliggi un colpo critico.", nil, 0xb0e96ef5, nil, "um" },
  [1226127] = { nil, "Velocità d'attacco in mischia aumentata del $N1%.", nil, 0xd471470c, "mu" },
  [1226132] = { "I tuoi tiri infliggono il $N1% di danni in più ai bersagli colpiti dal tuo Morso del Serpente.", nil, 0x2ccc126f, nil, "um" },
  [1226136] = { nil, "Potenza d'attacco aumentata del $N1%.", nil, 0xfe0a7d88, "mu" },
  [1226137] = { "I tuoi colpi critici a distanza aumentano la tua potenza d'attacco del $N1% per $D1.", nil, 0x0dd02dbc, nil, "um" },
  [1226138] = { "Il tuo Tiro Multiplo colpisce $N1 bersagli aggiuntivi, e i colpi del tuo Tiro Mortale e del tuo Tiro della Chimera aumentano del $N3% i danni inflitti dal tuo prossimo Tiro Multiplo lanciato entro $D1, effetto cumulabile fino a $N4 volte.", nil, 0x88a55aa6, nil, "um" },
  [1226210] = { { "Potenzia la tua cintura per conferirle l'effetto seguente:\n\nTi teletrasporta in avanti di $N1 m.\n\nQuesto potenziamento è permanente e non può essere rimosso né sostituito.", "Potenzia la tua cintura per conferirle l'effetto seguente:\n\nTi teletrasporta in avanti di $N1 m.\n\n", shape = { "1/0", "1/0" }, key = { "b91078746269d64b", "9864d0a3df676ee4" } }, nil, 0x2f36e00d, nil, "um" },
  [1226211] = { { "Potenzia la tua cintura per conferirle l'effetto seguente:\n\nAttiva una serie di propulsori che aumentano la velocità di movimento fino al $N1% per un massimo di $D1.\n\nQuesto potenziamento è permanente e non può essere rimosso né sostituito.", "Potenzia la tua cintura per conferirle l'effetto seguente:\n\nAttiva una serie di propulsori che aumentano la velocità di movimento fino al $N1% per un massimo di $D1.\n\n", shape = { "2/1", "2/1" }, key = { "59b14f19fc2c845d", "35fc5476505f8d10" } }, nil, 0xaa21fad9, nil, "um" },
  [1226212] = { { "Potenzia la tua cintura per conferirle l'effetto seguente:\n\nAltera un campo magnetico tra te e il nemico vicino che hai come bersaglio, respingendovi a vicenda.\n\nHa effetto solo su bersagli fino a $N1 livelli superiori al tuo. Alcuni bersagli non possono essere spostati. Un bersaglio può subire questo effetto solo una volta ogni $D1.\n\nQuesto potenziamento è permanente e non può essere rimosso né sostituito.", "Potenzia la tua cintura per conferirle l'effetto seguente:\n\nAltera un campo magnetico tra te e il nemico vicino che hai come bersaglio, respingendovi a vicenda.\n\nHa effetto solo su bersagli fino a $N1 livelli superiori al tuo. Alcuni bersagli non possono essere spostati. Un bersaglio può subire questo effetto solo una volta ogni $D1.\n\n", shape = { "2/1", "2/1" }, key = { "3346e3991761ca7e", "2971812542ae9ac0" } }, nil, 0xc1bfd040, nil, "um" },
  [1226215] = { "Getta la prudenza alle ortiche e metti alla prova il tentativo di un goblin di costruire un dispositivo di teletrasporto. Con un po' di fortuna arriverai a New Avalon senza perdere pezzi.", nil, 0x80d2cc12, nil, "um" },
  [1226217] = { "Getta la prudenza alle ortiche e metti alla prova il tentativo di un goblin di costruire un dispositivo di teletrasporto. Con un po' di fortuna arriverai a New Avalon senza perdere pezzi.", nil, 0x8442a0f2, nil, "um" },
  [1226218] = { nil, "Danni aggiuntivi subiti da ⟦Mark of Zeliek=Marchio di Zeliek⟧.", nil, 0x68fb058f, "mu" },
  [1226219] = { nil, "Danni aggiuntivi subiti da ⟦Mark of Blaumeux=Marchio di Blaumeux⟧.", nil, 0x4f8d77be, "mu" },
  [1226220] = { nil, "Danni aggiuntivi subiti da Mark of Mograine.", nil, 0x83591c01, "mu" },
  [1226221] = { nil, "Danni aggiuntivi subiti da ⟦Mark of Korth'azz=Marchio di Korth'azz⟧.", nil, 0x49cfbbed, "mu" },
  [1226282] = { "Lancia un dardo di magia oscura contro un bersaglio nemico, infliggendo danni da ombra.", nil, 0x42ce8448, nil, "um" },
  [1226310] = { nil, "Danni da acido ogni $D1.", nil, 0xf0303063, "mu" },
  [1226340] = { "I tuoi assalti e il tuo Morso della Mangusta infliggono il $N1% di danni in più ai bersagli colpiti dal tuo Morso del Serpente o dal tuo Wyvern Strike.", nil, 0x18ac3d55, nil, "um" },
  [1226350] = { "Usalo su una Corrupted Vine.", nil, 0x02d7c631, nil, "um" },
  [1226357] = { nil, "Velocità d'attacco aumentata del $N1%.", nil, 0x8859e2db, "mu" },
  [1226359] = { "I tuoi colpi critici in mischia aumentano la tua velocità d'attacco del $N1% per $D1.", nil, 0x39d2c346, nil, "um" },
  [1226365] = { "Aumenta di un ulteriore $N1% per accumulo il bonus ai danni di Raptor Fury.", nil, 0xcda81970, nil, "um" },
  [1226377] = { nil, "Cure derivanti dal lancio di Mago aumentate del $N1%.", nil, 0x2d491f2e, "mu" },
  [1226378] = { "Riduce di $D1 il tempo di recupero del tuo ⟦Arcane Power=Potere Arcano⟧ e ne aumenta la durata di $D2. Mentre ⟦Arcane Power=Potere Arcano⟧ è attivo, la tua probabilità di ottenere Arcane Tunneling aumenta del $N3% e ogni lancio di ⟦Arcane Blast=Detonazione Arcana⟧ riduce di $D3 il tempo di recupero residuo di Rigenerazione di Massa.", nil, 0xa68805e9, nil, "um" },
  [1226396] = { "Ti permette di guardare molto lontano alla ricerca di mele.", "Sta spiando delle mele.", 0xe9331d6c, 0x2d890a31, "uu" },
  [1226402] = { "Ruba una mela da distanza di sicurezza.", nil, 0xceded9ff, nil, "um" },
  [1226406] = { nil, "Il tuo prossimo incantesimo arcano di danno o di cura non consumerà l'effetto di ⟦Arcane Blast=Detonazione Arcana⟧.", nil, 0x3c528f91, "mu" },
  [1226407] = { "La tua ⟦Arcane Blast=Detonazione Arcana⟧ ha una probabilità del $N1% di attivare Arcane Tunneling. Arcane Tunneling impedisce che l'effetto della tua ⟦Arcane Blast=Detonazione Arcana⟧ venga consumato dal prossimo altro incantesimo che infligge danni da arcano che lanci. Inoltre, attivare ⟦Arcane Power=Potere Arcano⟧ azzera il tempo di recupero della tua Rigenerazione di Massa.", nil, 0x65413990, nil, "um" },
  [1226414] = { nil, "Danni subiti ridotti del $N1%.", nil, 0x0a593335, "mu" },
  [1226415] = { "Riavvolgimento Temporale riduce anche del $N1% tutti i danni subiti dal tuo bersaglio per $D1.", nil, 0xac70f141, nil, "um" },
  [1226423] = { "La tua ⟦Living Bomb=Bomba Vivente⟧ ora infligge danni ogni $D1 ed esplode se il bersaglio muore. Inoltre, l'effetto di Glaciazione della runa di Lancia di Ghiaccio ora si accumula fino a $N2 volte, e Dardo di Geloincanto conferisce $N3 accumuli ogni volta che colpisce.", nil, 0x94a0866d, nil, "um" },
  [1226432] = { "Riduce di $D1 il tempo di recupero del tuo incantesimo Globo Congelato. Ogni volta che Glaciazione viene consumata, il tempo di recupero del tuo Gelo Profondo si riduce di $D2 per ogni accumulo consumato. Riduce di $D3 il tempo di recupero di ⟦Fire Blast=Detonazione di Fuoco⟧, e ⟦Fire Blast=Detonazione di Fuoco⟧ ora rinnova la durata della tua ⟦Living Bomb=Bomba Vivente⟧ sul bersaglio.", nil, 0x02e5e263, nil, "um" },
  [1226446] = { "Lanciare Gelo Profondo aumenta di $D1 la durata residua del tuo incantesimo Vene Gelide. Lanciare Pirosfera annulla $N2 accumuli dell'effetto del tuo Balefire Bolt.", nil, 0x8e5bb0cb, nil, "um" },
  [1226451] = { nil, nil, nil, 0x16d3929f, "me" },
  [1226452] = { "⟦Lay on Hands=Mano Celestiale⟧ ti conferisce il $N1% di celerità degli incantesimi per $D1 e riduce di $N4 s il tempo di recupero globale dei tuoi prossimi $N3 incantesimi Luce Divina, ⟦Holy Light=Luce Sacra⟧, ⟦Flash of Light=Lampo di Luce⟧ o ⟦Holy Shock=Folgore Sacra⟧.", nil, 0x1169d163, nil, "um" },
  [1226454] = { "Il tuo Faro di Luce ora si attiva anche quando curi il bersaglio del tuo Faro di Luce, ma con un'efficacia ridotta del $N1%.", nil, 0xaed47109, nil, "um" },
  [1226459] = { "Un ulteriore $N1% delle tue cure viene trasferito al bersaglio del tuo Faro di Luce.", nil, 0x68f11c77, nil, "um" },
  [1226460] = { "Quando hai equipaggiata un'arma a due mani, ⟦Crusader Strike=Assalto del Crociato⟧ ed Esorcismo ti conferiscono ⟦Holy Power=Potere Sacro⟧, che aumenta del $N1% tutti i danni da sacro che infliggi, effetto cumulabile fino a $N2 volte.", nil, 0xab6bcd9e, nil, "um" },
  [1226461] = { nil, "Aumenta del $N1% tutti i danni da sacro che infliggi.", nil, 0xe7943df9, "mu" },
  [1226462] = { "Tempesta Divina, ⟦Holy Shock=Folgore Sacra⟧ e ⟦Holy Wrath=Ira Sacra⟧ consumano tutto il tuo ⟦Holy Power=Potere Sacro⟧ e infliggono il $N1% di danni in più per ogni ⟦Holy Power=Potere Sacro⟧ accumulato, con un'efficacia del $N2% contro i bersagli controllati da giocatori.", nil, 0xadd6ae7d, nil, "um" },
  [1226463] = { "Consumare ⟦Holy Power=Potere Sacro⟧ aumenta la tua potenza d'attacco del $N1% per ogni ⟦Holy Power=Potere Sacro⟧ consumato per $D1.", nil, 0x82e61b29, nil, "um" },
  [1226464] = { nil, "Aumenta del $N1% la potenza d'attacco.", nil, 0x0dd3c23b, "mu" },
  [1226466] = { nil, "Aumenta del $N1% l'indice di blocco.", nil, 0x6f336ed6, "mu" },
  [1226467] = { "Shield of Righteousness aumenta anche il tuo indice di blocco del $N1% per $D1.", nil, 0x5e3d3c30, nil, "um" },
  [1226477] = { "Shield of Righteousness infligge una percentuale di danni in più pari alla tua probabilità di bloccare.", nil, 0xbd930192, nil, "um" },
  [1226479] = { "La tua Ira Vendicatrice non attiva più Rigorosità, dura $D1 in più e aumenta il tuo indice di blocco del $N2%.", nil, 0xc623b968, nil, "um" },
  [1226499] = { "Riduce di $D1 il tempo di recupero di Parola del Potere: Barriera, ed Eruzione di Luce ora rende istantanei anche ⟦Prayer of Healing=Preghiera di Cura⟧ e ⟦Greater Heal=Cura Maggiore⟧.", nil, 0xc045dc38, nil, "um" },
  [1226500] = { nil, "Tempo di lancio del tuo prossimo incantesimo Cura Inferiore, Cura, ⟦Greater Heal=Cura Maggiore⟧, ⟦Flash Heal=Cura Rapida⟧, Cura Combinata o ⟦Prayer of Healing=Preghiera di Cura⟧ ridotto del $N1%.", nil, 0xb68354a5, "mu" },
  [1226501] = { "Aumenta del $N1% le cure di Circolo di Guarigione e Contrizione. Inoltre, il tempo di recupero del tuo Spirito del Redentore è ridotto di $D1 e le tue cure aumentano del $N3% mentre il tuo Spirito del Redentore è attivo.", nil, 0xd0a9b1c3, nil, "um" },
  [1226502] = { nil, "Cura $N1 danni ogni $N2 s.", nil, 0x9b5d5888, "mu" },
  [1226529] = { nil, "In questo barile c'è ancora del pesce!", nil, 0x6d9b69d4, "mu" },
  [1226565] = { "I lanci di ⟦Power Word: Shield=Parola del Potere: Scudo⟧ curano istantaneamente il bersaglio del $N1% del valore assorbito, e gli incantesimi potenziati da Provvidenza hanno le cure aumentate del $N2% per accumulo.", nil, 0x957edc9f, nil, "um" },
  [1226585] = { "Il tuo ⟦Mind Flay=Flagello Mentale⟧ e la tua Risonanza Mentale non perdono più durata quando subisci danni durante la canalizzazione. Inoltre, infliggono il $N1% di danni in più per ogni altro tuo effetto periodico d'ombra sul bersaglio, fino a un aumento massimo del $N2%.", nil, 0x030c250c, nil, "um" },
  [1226591] = { "La tua ⟦Mind Blast=Detonazione Mentale⟧ genera il $N1% di minaccia in meno e ottiene un aumento dei danni del $N2% per ogni accumulo di Aculeo Mentale sul bersaglio.", nil, 0x2719cceb, nil, "um" },
  [1226595] = { "I danni inflitti dal tuo ⟦Mind Flay=Flagello Mentale⟧ ora aumentano quanto più a lungo canalizzi l'incantesimo. Ogni volta che infligge danni, i danni successivi aumentano del $N1%. L'effetto si azzera a ogni nuova canalizzazione.", nil, 0x67a4aa9c, nil, "um" },
  [1226739] = { nil, "Danni e danni critici inflitti ai Non Morti aumentati del $N1%.", nil, 0xd6f5d105, "mu" },
  [1226800] = { "Riponi nella cassa un pezzo di equipaggiamento della ⟦Scarlet Crusade=Crociata Scarlatta⟧ creato da te. L'oggetto verrà distrutto per sempre.", nil, 0xef045547, nil, "um" },
  [1226808] = { "Rigenera il $N1% della salute e del mana al secondo per $D1. Devi sederti per mangiare.", "Rigenera il $N1% della salute e del mana al secondo.", 0x9265d95a, 0x68f16274, "uu" },
  [1226810] = { "Velocità di movimento ridotta del $N1%.", nil, 0x08fe36e7, nil, "um" },
  [1226814] = { { "Rigenera $N1 salute e $N2 mana in $D1. Ancora più buono dentro Naxxramas: rigenera invece il $N4% della salute e il $N5% del mana in $D2. Devi sederti per mangiare.", "Rigenera $N1 salute e $N2 mana in $D1.  Devi sederti per mangiare.", shape = { "6/2", "3/1" } }, "Rigenera $N1 salute e $N2 mana al secondo.", 0xdceec844, 0x41faa520, "uu" },
  [1226843] = { "Mentre Just a Flesh Wound non è attivo, Pugnalata alle Spalle, ⟦Sinister Strike=Assalto Funesto⟧, Fendente di Sciabola e Mutilazione infliggono il $N1% di danni in più per ogni tuo effetto di veleno o di sanguinamento attivo sul bersaglio, fino a un aumento massimo del $N2%.", nil, 0xd71a835f, nil, "um" },
  [1226869] = { "I colpi critici dei tuoi veleni e dei tuoi attacchi automatici hanno una probabilità del $N1% di conferirti un punto combo.", nil, 0xeca30699, nil, "um" },
  [1226871] = { "Aumenta del $N1% i danni di Imboscata, Sventramento, Tempesta Cremisi e Affondo Venefico.", nil, 0x0fa58f03, nil, "um" },
  [1226874] = { "I tuoi accumuli di Rolling with the Punches aumentano anche del $N1% tutti i danni che infliggi.", nil, 0x31fa5d43, nil, "um" },
  [1226882] = { "Il tuo ⟦Blade Flurry=Vortice di Lame⟧ ora colpisce anche un terzo bersaglio e aumenta la tua velocità d'attacco di un ulteriore $N1%. Inoltre, ogni punto combo che spendi riduce di $D1 il tempo di recupero residuo del tuo ⟦Blade Flurry=Vortice di Lame⟧.", nil, 0x59329a26, nil, "um" },
  [1226883] = { nil, "⟦Blade Flurry=Vortice di Lame⟧.", nil, 0xb4e9bb2e, "mu" },
  [1226956] = { "Il tuo Rolling with the Punches ora conferisce il $N1% di salute in più e il $N2% di danni in più per accumulo. Con $N3 accumuli, ogni volta che schivi o pari ottieni $N4 energia.", nil, 0x4cf3ca3b, nil, "um" },
  [1226961] = { "Quando il tuo ⟦Lava Burst=Getto di Lava⟧, la tua ⟦Chain Lightning=Catena di Fulmini⟧ o il tuo ⟦Lightning Bolt=Dardo Fulminante⟧ colpisce un bersaglio afflitto dalla tua ⟦Flame Shock=Folgore del Fuoco⟧ di Grado $N1 o di Grado $N2, infligge anche un impulso dei danni di ⟦Flame Shock=Folgore del Fuoco⟧.", nil, 0xe3c1286e, nil, "um" },
  [1226977] = { "La probabilità di attivare Sovraccarico aumenta di un ulteriore $N1% e i danni di ⟦Lava Burst=Getto di Lava⟧ aumentano di una percentuale pari alla tua probabilità di critico magico. Quando ⟦Lightning Bolt=Dardo Fulminante⟧ o ⟦Chain Lightning=Catena di Fulmini⟧ infliggono danni, aumentano del $N3% i danni inflitti dal tuo prossimo ⟦Lava Burst=Getto di Lava⟧ lanciato entro $D1, effetto cumulabile fino a $N4 volte.", nil, 0x5e2b493a, nil, "um" },
  [1226978] = { "Quando la tua ⟦Chain Lightning=Catena di Fulmini⟧ danneggia meno di $N1 bersagli, infligge il $N2% di danni in più per ogni bersaglio in meno rispetto a $N3.", nil, 0x850336b6, nil, "um" },
  [1226981] = { "I danni inflitti da te o dal demone che hai evocato hanno una probabilità del $N1% di aumentare del $N2% i danni inflitti dall'altro per $D1.", nil, 0x3d3f4a2e, nil, "um" },
  [1226984] = { "Mentre Folgore Statica è attiva, Sferzata Lavica, ⟦Lava Burst=Getto di Lava⟧ e Assalto della Tempesta hanno il $N1% di probabilità di aggiungere una carica al tuo ⟦Lightning Shield=Scudo di Fulmini⟧. Se le cariche superano $N2, ⟦Lightning Shield=Scudo di Fulmini⟧ infligge subito danni al bersaglio invece di aggiungere cariche.", nil, 0x168b9084, nil, "um" },
  [1226986] = { "Riduce del $N1% il tempo di recupero del tuo ⟦Fire Nova Totem=Totem dell'Esplosione di Fuoco⟧, ne aumenta i danni del $N2% e ne riduce il costo in mana del $N3%. Inoltre, il tuo ⟦Fire Nova Totem=Totem dell'Esplosione di Fuoco⟧ ora si attiva istantaneamente quando viene lanciato.", nil, 0x2812c13b, nil, "um" },
  [1226997] = { "Arma del Maelstrom ora può cumulare fino a $N1 cariche. Con un'arma a due mani ottieni $N2 cariche alla volta. Gli incantesimi lanciati con più di $N3 cariche infliggono danni o cure aumentati del $N4% per ogni carica in eccesso. Gli incantesimi lanciati con $N5 cariche consumano tutte le cariche e vengono lanciati due volte.", nil, 0xb75eaa2c, nil, "um" },
})
